namespace AMGH.ITInventory.Application.Abstractions.Storage;

/// <summary>Stores uploaded files outside the web root. Names are generated by the application, never by users.</summary>
public interface IFileStorage
{
    Task SaveAsync(string area, string storedFileName, Stream content, CancellationToken cancellationToken = default);
    Task<Stream?> OpenReadAsync(string area, string storedFileName, CancellationToken cancellationToken = default);
    Task DeleteAsync(string area, string storedFileName, CancellationToken cancellationToken = default);
}

public static class StorageAreas
{
    public const string AssetDocuments = "assets";
    public const string PendingImports = "_imports";
}
